/// <summary>
/// CB166_SalesOrderSubstitutes
/// Post sales order creation processing multithread batch task
/// inspired from new class LedgerJournalBatchPost
/// </summary>
class METTMSEngineOrderProcessTaskService extends METSysOperationTaskService
{
    guid                topPickingProcessId;
    CustAccount         custAccount;
    InventLocationId    inventLocationId;

}

Method.Source:
/// <summary>
/// Executes the main process.
/// </summary>
/// <param name = "_contract">
/// <c>METPostSalesOrderCreationProcessingContract</c>.
/// </param>
public void process(METTMSEngineOrderProcessContract _contract)
{
    this.processInternal(_contract);
}

/// <summary>
/// Process the batch tasks.
/// </summary>
/// <param name = "_readPast">Read past table setting.</param>
public void processTask(boolean _readPast)
{
    while (this.getCustAccountFromTopPickingQueue(topPickingProcessId, _readPast))
    {
        try
        {
            if (this.custAccount && this.inventLocationId)
            {
                this.execute(this.custAccount, this.inventLocationId);
            }
        }
        catch (Exception::Error)
        {
            // Catch any exception so that any one error won't bring down
            // the entire process of sales order substitution.
            Global::exceptionTextFallThrough();
        }
    }
}

/// <summary>
/// Initializes the object.
/// </summary>
protected void initialise()
{
    super();

    // get the topPickingProcessId from the contract
    METTMSEngineOrderProcessContract contract = dataContract as METTMSEngineOrderProcessContract;
    topPickingProcessId = contract.parmTopPickingProcessId();
}

/// <summary>
/// Executes the main process.
/// </summary>
/// <param name = "_custAccount">vendor account number.</param>
/// <param name = "_inventLocationId">Sales order location id.</param>
private void execute(CustAccount _custAccount, InventLocationId _inventLocationId)
{
    METTMSEngineOrderProcessContract    contract = dataContract as METTMSEngineOrderProcessContract;
    SalesTable                          salesTable;

    // <--- FIX: Load the query from the contract to respect original user filters --->
    Query                   query = contract.getQuery();
    QueryBuildDataSource    qbdsSalesTable, qdbsMetSalesTable;
    QueryRun                qr;
    // Taking the original query from the contract and adding filters to it.
    // This is required to respect user filters along with our additional filters.
    qbdsSalesTable      = query.dataSourceTable(tableNum(SalesTable));
    qdbsMetSalesTable   = query.dataSourceTable(tableNum(METSalesTable));

    container salesCon  = contract.parmSalesContainer();

    if (salesCon != conNull())
    {
        qdbsMetSalesTable.clearRange(fieldNum(METSalesTable, OrderProcessingStatus));

        for(int i=1; i<= conLen(salesCon); i++)
        {
            qbdsSalesTable.addRange(fieldNum(SalesTable, SalesId)).value(SysQuery::value(conPeek(salesCon, i)));
        }
    }
    //  Apply the Task Grouping filters (Lock it to this specific Customer & Warehouse)
    qbdsSalesTable.addRange(fieldNum(SalesTable, CustAccount)).value(queryValue(_custAccount));
    qbdsSalesTable.addRange(fieldNum(SalesTable, InventLocationId)).value(queryValue(_inventLocationId));

    qr = new QueryRun(query);

    while (qr.next())
    {
        salesTable = qr.get(tableNum(SalesTable));

        // Step 4: Call TMS engine outside of the db transaction so it does not rollback substitutes
        METTMSEngineOrderProccess metTMSEngineOrderProccess = METTMSEngineOrderProccess::construct(METTMSEngineExecutionMode::SalesOrderCreation, salesTable);
        metTMSEngineOrderProccess.run();
    }
}

/// <summary>
/// Get sales order id to substitute from the top picking queue <c>METPostSalesOrderCreationProcessingQueue</c>
/// </summary>
/// <param name = "_processId">Guid created and added in the contract <c>METPostSalesOrderCreationProcessingContract</c></param>
/// <param name = "_readPast">boolean to read past records or not</param>
/// <returns>Get sales order id to substitute</returns>
private CustAccount getCustAccountFromTopPickingQueue(guid _processId, boolean _readPast)
{
    METPostSalesOrderCreationProcessingQueue postQueue;

    #OCCRetryCount
    int backOffWait;
    Microsoft.Dynamics.Ax.Xpp.DeadlockException deadLockException;
    Microsoft.Dynamics.Ax.Xpp.UpdateConflictException updateConflictException;
    Microsoft.Dynamics.Ax.Xpp.TransientSqlConnectionError transientSqlConnectionError;

    postQueue.readPast(_readPast);

    try
    {
        ttsbegin;

        select firstonly pessimisticlock *
        from postQueue
        where postQueue.ProcessId == _processId;

        if (postQueue.RecId)
        {
            this.custAccount      = postQueue.CustAccount;
            this.inventLocationId = postQueue.InventLocationId;
            postQueue.delete();
        }
        else
        {
            this.custAccount      = '';
            this.inventLocationId = '';
        }
        ttscommit;
    }
    catch (deadLockException)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() < #RetryNum)
            {
                backOffWait = RandomGenerate::construct().randomInt(100, 5000);
                sleep(xSession::currentRetryCount() * backOffWait);
                retry;
            }
            else
            {
                throw deadLockException;
            }
        }
        else
        {
            throw deadLockException;
        }
    }
    catch (updateConflictException)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() < #RetryNum)
            {
                backOffWait = RandomGenerate::construct().randomInt(100, 5000);
                sleep(xSession::currentRetryCount() * backOffWait);
                retry;
            }
            else
            {
                throw Exception::UpdateConflictNotRecovered;
            }
        }
        else
        {
            throw updateConflictException;
        }
    }
    catch (transientSqlConnectionError)
    {
        if (SysTransientSqlConnectionErrorHandler::retryTransientSqlConnectionError())
        {
            retry;
        }
        else
        {
            throw transientSqlConnectionError;
        }
    }

    return this.custAccount;
}
